mapper.select:
SELECT COALESCE(SUM(quantity), 0)
FROM asset
WHERE account_id = #{accountId} 
  AND stock_code = #{stockCode}

mapper.update:
UPDATE asset 
SET 
    quantity = quantity - #{quantity},
    purchase_amount = purchase_amount - (avg_price * #{quantity}),
    updated_at = NOW()
WHERE account_id = #{accountId} 
  AND stock_code = #{stockCode} 
  AND quantity >= #{quantity}

UPDATE account 
SET balance = balance + #{amount} 
WHERE account_id = #{accountId}

UPDATE account 
SET balance = balance - #{amount} 
WHERE account_id = #{accountId} 
  AND balance >= #{amount}

mapper.delete:
DELETE FROM asset 
WHERE account_id = #{accountId} 
  AND stock_code = #{stockCode} 
  AND quantity <= 0

mapper.update:
UPDATE asset
SET
    quantity = quantity - #{quantity},
    purchase_amount = purchase_amount - #{costBasis},
    updated_at = NOW()
WHERE account_id = #{accountId}
  AND stock_code = #{stockCode}
